func (s MapDiveStruct) JSONSize() int {
	size := 37
	size += len(s.Clamped) * 24
	for k := range s.Clamped {
		size += len(k) * 2
	}
	size += len(s.Counts) * 24
	for k := range s.Counts {
		size += len(k) * 2
	}
	size += len(s.Names) * 4
	for k, v := range s.Names {
		size += len(k) * 2
		size += len(v)*2 + 2
	}
	return size
}

