func (s Address) JSONSize() int {
	size := 36
	size += len(s.City) * 2
	size += len(s.Street) * 2
	size += len(s.ZipCode) * 2
	return size
}

func (s Address) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"city\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.City)
	dst = append(dst, ",\"street\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.Street)
	dst = append(dst, ",\"zipCode\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.ZipCode)
	return append(dst, '}'), nil
}

