func (s Node) JSONSize() int {
	size := 120
	if n := len(s.Children); n > 0 {
		size += n - 1
	}
	for i0 := range s.Children {
		size += s.Children[i0].JSONSize()
	}
	size += len(s.Name) * 2
	size += len(s.Props) * 4
	for k, v := range s.Props {
		size += len(k) * 2
		size += len(v)*2 + 2
	}
	if n := len(s.Tags); n > 0 {
		size += n - 1
	}
	for i0 := range s.Tags {
		size += len(s.Tags[i0])*2 + 2
	}
	return size
}

func (s Node) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"active\":"...)
	dst = strconv.AppendBool(dst, s.Active)
	dst = append(dst, ",\"children\":"...)
	if s.Children == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '[')
		if len(s.Children) > 0 {
			if dst, err = s.Children[0].AppendJSON(dst); err != nil {
				return dst, err
			}
			for _, v0 := range s.Children[1:] {
				dst = append(dst, ',')
				if dst, err = v0.AppendJSON(dst); err != nil {
					return dst, err
				}
			}
		}
		dst = append(dst, ']')
	}
	dst = append(dst, ",\"id\":"...)
	dst = strconv.AppendInt(dst, s.ID, 10)
	dst = append(dst, ",\"name\":\""...)
	dst = encode.AppendStringNoHTML(dst, s.Name)
	dst = append(dst, ",\"props\":"...)
	if s.Props == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '{')
		{
			first := true
			for k, v := range s.Props {
				if first {
					first = false
					dst = append(dst, '"')
				} else {
					dst = append(dst, ",\""...)
				}
				dst = encode.AppendStringNoHTML(dst, k)
				dst = append(dst, ":\""...)
				dst = encode.AppendStringNoHTML(dst, v)
			}
		}
		dst = append(dst, '}')
	}
	dst = append(dst, ",\"score\":"...)
	if dst, err = encode.AppendFloat(dst, s.Score, 64); err != nil {
		return dst, err
	}
	dst = append(dst, ",\"tags\":"...)
	if s.Tags == nil {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '[')
		if len(s.Tags) > 0 {
			dst = append(dst, '"')
			dst = encode.AppendStringNoHTML(dst, s.Tags[0])
			for _, v0 := range s.Tags[1:] {
				dst = append(dst, ",\""...)
				dst = encode.AppendStringNoHTML(dst, v0)
			}
		}
		dst = append(dst, ']')
	}
	return append(dst, '}'), nil
}

