func (s SQLNullStruct) JSONSize() int {
	size := 194
	size += len(s.S.String) * 2
	return size
}

func (s SQLNullStruct) AppendJSON(dst []byte) ([]byte, error) {
	var err error
	_ = err
	dst = append(dst, "{\"b\":"...)
	if !s.B.Valid {
		dst = append(dst, "null"...)
	} else {
		dst = strconv.AppendUint(dst, uint64(s.B.Byte), 10)
	}
	dst = append(dst, ",\"bl\":"...)
	if !s.BL.Valid {
		dst = append(dst, "null"...)
	} else {
		dst = strconv.AppendBool(dst, s.BL.Bool)
	}
	dst = append(dst, ",\"f\":"...)
	if !s.F.Valid {
		dst = append(dst, "null"...)
	} else {
		if dst, err = encode.AppendFloat(dst, s.F.Float64, 64); err != nil {
			return dst, err
		}
	}
	dst = append(dst, ",\"i\":"...)
	if !s.I.Valid {
		dst = append(dst, "null"...)
	} else {
		dst = strconv.AppendInt(dst, s.I.Int64, 10)
	}
	dst = append(dst, ",\"i16\":"...)
	if !s.I16.Valid {
		dst = append(dst, "null"...)
	} else {
		dst = strconv.AppendInt(dst, int64(s.I16.Int16), 10)
	}
	dst = append(dst, ",\"i32\":"...)
	if !s.I32.Valid {
		dst = append(dst, "null"...)
	} else {
		dst = strconv.AppendInt(dst, int64(s.I32.Int32), 10)
	}
	dst = append(dst, ",\"s\":"...)
	if !s.S.Valid {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = encode.AppendStringNoHTML(dst, s.S.String)
	}
	dst = append(dst, ",\"t\":"...)
	if !s.T.Valid {
		dst = append(dst, "null"...)
	} else {
		dst = append(dst, '"')
		dst = s.T.Time.AppendFormat(dst, time.RFC3339Nano)
		dst = append(dst, '"')
	}
	return append(dst, '}'), nil
}
